template.script:
            const sendBtn = document.getElementById('chatbot_send');
            const input = document.getElementById('chatbot_input');
            const responseDiv = document.getElementById('chatbot_response');

            sendBtn.addEventListener('click', function () {
                const message = input.value.trim();
                if (!message) {
                    alert("Écris ta question !");
                    return;
                }
                input.value = '';
                responseDiv.textContent = "Chargement...";

                fetch('/chatbot/message', {
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'X-Requested-With': 'XMLHttpRequest',
    },
    body: JSON.stringify({text: message}),
    credentials: 'same-origin',
})

                .then(res => res.json())
                .then(data => {
    console.log('Réponse reçue:', data);
    responseDiv.textContent = (data.result ? data.result.response : null) || "Pas de réponse.";


})

                .catch(() => {
                    responseDiv.textContent = "Erreur lors de la communication.";
                });
            });
